create role anon;create role authenticated;create role service_role bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql as $$select null::uuid$$;
create table customers(id uuid primary key default gen_random_uuid(),owner_id uuid,name text,email text,phone text,address text,city text,state text,zip text,created_at timestamptz default now());
create table jobs(id uuid primary key default gen_random_uuid(),owner_id uuid,customer_id uuid references customers(id),title text,service_type text,status text default 'scheduled',address text,notes text,scheduled_at timestamptz,assigned_to uuid,created_at timestamptz default now(),updated_at timestamptz default now());
create table estimates(id uuid primary key default gen_random_uuid(),owner_id uuid,customer_id uuid references customers(id),job_id uuid references jobs(id),estimate_number bigint generated always as identity,title text,description text,notes text,status text default 'draft' check(status in ('draft','sent','approved','declined','converted')),subtotal numeric,tax numeric default 0,total numeric,valid_until date,approved_at timestamptz,sent_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table estimate_items(id uuid primary key default gen_random_uuid(),estimate_id uuid references estimates(id) on delete cascade,description text,quantity numeric,unit_price numeric,line_total numeric,sort_order int);
create table invoices(id uuid primary key default gen_random_uuid(),owner_id uuid,customer_id uuid references customers(id),job_id uuid references jobs(id),estimate_id uuid references estimates(id),invoice_number bigint generated always as identity,title text,description text,notes text,status text default 'draft' check(status in ('draft','sent','partial','paid','void','overdue')),subtotal numeric,tax numeric default 0,total numeric,amount_paid numeric default 0,due_at timestamptz,paid_at timestamptz,sent_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table invoice_items(id uuid primary key default gen_random_uuid(),invoice_id uuid references invoices(id) on delete cascade,description text,quantity numeric,unit_price numeric,line_total numeric,sort_order int);
create table payments(id uuid primary key default gen_random_uuid(),invoice_id uuid references invoices(id),amount numeric,method text,status text,paid_at timestamptz default now(),created_at timestamptz default now());
create table job_materials(id uuid primary key default gen_random_uuid(),job_id uuid references jobs(id),description text,quantity numeric,unit_price numeric,unit_cost numeric,supplier text,markup_percent numeric,billable boolean default true,created_at timestamptz default now());
grant all on all tables in schema public to service_role;grant usage,select on all sequences in schema public to service_role;
